CREATE OR REPLACE FUNCTION public.accept_my_staff_invitation() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.staff_invitations;_email text:=lower(auth.jwt()->>'email');BEGIN IF auth.uid() IS NULL OR _email IS NULL THEN RETURN false;END IF;SELECT * INTO i FROM public.staff_invitations si WHERE si.email=_email AND si.status='sent' AND si.expires_at>now() ORDER BY si.created_at DESC LIMIT 1 FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;IF NOT EXISTS(SELECT 1 FROM public.roles r WHERE r.code=i.role AND r.is_active) THEN RAISE EXCEPTION 'الدور موقوف';END IF;UPDATE public.user_role_assignments SET is_active=false WHERE user_id=auth.uid();UPDATE public.user_roles SET is_active=false WHERE user_id=auth.uid();INSERT INTO public.user_role_assignments(user_id,role,assigned_by,reason) VALUES(auth.uid(),i.role,i.invited_by,'قبول دعوة موظف') ON CONFLICT(user_id,role) DO UPDATE SET is_active=true,assigned_by=excluded.assigned_by,assigned_at=now();UPDATE public.staff_invitations SET status='accepted',accepted_by=auth.uid(),accepted_at=now() WHERE id=i.id;PERFORM public._safety_audit('STAFF_INVITATION_ACCEPTED','staff_invitations',i.id::text,NULL,jsonb_build_object('role',i.role),'قبول دعوة موظف');RETURN true;END $$;
SELECT to_regprocedure('public.accept_my_staff_invitation()') IS NOT NULL AS acceptance_ready;